async function configureRepository() {
  // Generated by Pages workflow; no account names or release URLs are hardcoded.
  const response = await fetch('repository.json', { cache: 'no-cache' });
  if (!response.ok) return;
  const { repository } = await response.json();
  if (typeof repository !== 'string' || !/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repository)) return;
  const root = `https://github.com/${repository}`;
  const links = {
    repo: root, source: root, releases: `${root}/releases`,
    privacy: `${root}/blob/main/PRIVACY.md`, license: `${root}/blob/main/LICENSE`
  };
  for (const [name, url] of Object.entries(links)) {
    document.querySelectorAll(`[data-${name}]`).forEach(link => {
      link.href = url;
      link.hidden = false;
    });
  }
  const button = document.getElementById('download');
  button.href = `${root}/releases`;
  button.textContent = 'Перейти к скачиванию ↓';
  try {
    const latest = await fetch(`https://api.github.com/repos/${repository}/releases/latest`, {
      headers: { Accept: 'application/vnd.github+json' }
    });
    if (!latest.ok) return;
    const release = await latest.json();
    const asset = release.assets?.find(item => /^BashkortKeyboard-.+-win-x64\.zip$/i.test(item.name));
    if (!asset) return;
    const url = new URL(asset.browser_download_url);
    if (url.origin !== 'https://github.com' || !url.pathname.startsWith(`/${repository}/releases/download/`)) return;
    button.href = url.href;
    button.textContent = 'Скачать для Windows ↓';
    document.getElementById('release-note').textContent =
      `${release.tag_name} · ${Math.round(asset.size / 1024 / 1024)} МБ · Windows x64 · бесплатно`;
  } catch {
    // Releases link remains usable when API is offline or rate limited.
  }
}
configureRepository().catch(() => {});
